module shortest_path_edge_counter(input clk, input rst_n, input start, input [3:0] node_count, input [3:0] edge_count, input [3:0] edge_src [15:0], input [3:0] edge_dst [15:0], input [7:0] edge_weight [15:0], output reg [31:0] edge_usage [15:0], output reg done); localparam IDLE = 3'd0; localparam LOAD_EDGES = 3'd1; localparam COMPUTE_DISTANCES = 3'd2; localparam COUNT_PATHS = 3'd3; localparam DONE_STATE = 3'd4; reg [2:0] state; reg [3:0] node_count_reg; reg [3:0] edge_count_reg; reg [3:0] edge_src_reg [15:0]; reg [3:0] edge_dst_reg [15:0]; reg [7:0] edge_weight_reg [15:0]; reg [7:0] dist [7:7][7:7]; reg [31:0] path_count [7:7][7:7]; reg [31:0] edge_usage_reg [15:0]; reg done_reg; always @(posedge clk) begin if (!rst_n) begin state <= IDLE; node_count_reg <= 4'd0; edge_count_reg <= 4'd0; edge_src_reg <= 16'd0; edge_dst_reg <= 16'd0; edge_weight_reg <= 16'd0; for (int i=0; i<8; i++) begin for (int j=0; j<8; j++) begin if (i == j) dist[i][j] <= 8'd0; else dist[i][j] <= 8'd255; end end path_count <= 64'd0; edge_usage_reg <= 16{32'd0}; done_reg <= 1'b0; end else begin case (state) IDLE: begin if (start) state <= LOAD_EDGES; else state <= IDLE; end LOAD_EDGES: begin node_count_reg <= node_count; edge_count_reg <= edge_count; edge_src_reg <= edge_src; edge_dst_reg <= edge_dst; edge_weight_reg <= edge_weight; state <= COMPUTE_DISTANCES; end COMPUTE_DISTANCES: begin for (int k=0; k<8; k++) begin for (int i=0; i<8; i++) begin for (int j=0; j<8; j++) begin if (dist[i][j] > dist[i][k] + dist[k][j]) dist[i][j] <= dist[i][k] + dist[k][j]; end end end state <= COUNT_PATHS; end COUNT_PATHS: begin for (int i=0; i<8; i++) begin for (int j=0; j<8; j++) begin if (i == j) path_count[i][j] <= 32'd1; else path_count[i][j] <= 32'd0; end end for (int k=0; k<8; k++) begin for (int i=0; i<8; i++) begin for (int j=0; j<8; j++) begin if (dist[i][j] == dist[i][k] + dist[k][j]) path_count[i][j] <= path_count[i][j] + path_count[i][k] * path_count[k][j]; end end end state <= DONE_STATE; end DONE_STATE: begin for (int e=0; e<edge_count_reg; e++) begin int a = edge_src_reg[e]; int b = edge_dst_reg[e]; int weight = edge_weight_reg[e]; edge_usage_reg[e] <= 32'd0; for (int u=0; u<8; u++) begin for (int v=0; v<8; v++) begin if (dist[u][v] == dist[u][a] + weight + dist[b][v]) edge_usage_reg[e] <= edge_usage_reg[e] + path_count[u][a] * path_count[b][v]; end end end done_reg <= 1'b1; state <= DONE_STATE; end endcase end end assign edge_usage = edge_usage_reg; assign done = done_reg; endmodule